# Demo2 output mask transcribed rows (exclude cross row/col; 1=4)
obs=[{0,2,3,4,5,7,8,9},{0,2},{0,2,4,5,7,8},{0,2,4,8},set(),{0,2,4,8},{0,2,4,5,7,8},{0,2,7,8,9},{0,2,3,4,5,7,8,9},{0}]
import math
for formula in ['binom','and0','xor_even','prod_even']:
 best=(0,None)
 for a in range(-10,11):
  for b in range(-10,11):
   match=total=0
   for r in range(10):
    for c in range(10):
     if r==4 or c==6: continue
     x,y=r+a,c+b
     if formula=='binom': pred=(x>=0 and y>=0 and math.comb(x+y,x)%2==1)
     elif formula=='and0': pred=(x>=0 and y>=0 and (x&y)==0)
     elif formula=='xor_even': pred=(x+y)%2==0
     elif formula=='prod_even': pred=(x*y)%2==0
     match+= (pred == (c in obs[r])); total+=1
   if match>best[0]:best=(match,(a,b))
 print(formula,best,'/',total)

